macro.command:
// Amellwind unified rune controller + Partbreaker hooks
// Foundry v12 / dnd5e 4.4 / MidiQOL + DAE + Item Macro
// DAE: args[0] === "on" | "off" | "each"
const FLAG = "amellwind-toolbox";
const getRuneFlag = (doc, key) => foundry.utils.getProperty(doc, `flags.${FLAG}.${key}`);
const setRuneFlag = async (doc, key, value) => doc.update({ [`flags.${FLAG}.${key}`]: value });
const unsetRuneFlag = async (doc, key) => doc.update({ [`flags.${FLAG}.-=${key}`]: null });

const actorDoc = actor ?? item?.actor ?? item?.parent;
if (!item) return;
const arg0 = args?.[0];
const runeName = getRuneFlag(item, "runeName") ?? item.name;

const PARTBREAKER_HOOK_EVENTS = [
  "midi-qol.DamageRollComplete",
  "midi-qol.damageRollComplete",
];

function partbreakerTypeFromSet(types) {
  if (!types) return "";
  if (typeof types === "string") return types;
  if (Array.isArray(types)) return String(types[0] ?? "");
  if (typeof types?.[Symbol.iterator] === "function") {
    for (const t of types) return String(t ?? "");
  }
  return "";
}

function partbreakerIsWeaponAttack(wf) {
  const rolled = wf?.item;
  const itemType = String(rolled?.type ?? "").toLowerCase();
  const actType = String(wf?.activity?.type ?? "").toLowerCase();
  const actionType = String(wf?.itemActionType ?? wf?.defaultActivityType ?? "").toLowerCase();
  if (itemType === "spell") return false;
  if (itemType === "weapon") return true;
  if (["mwak", "rwak"].includes(actionType)) return true;
  if (actType === "attack" && itemType !== "equipment" && itemType !== "consumable") return true;
  return false;
}

function partbreakerIsCrit(wf) {
  // Strict checks only. DamageRoll.options.critical is often the numeric
  // threshold (20), which is truthy and caused false positives on normal hits.
  if (wf?.isCritical === true) return true;
  if (wf?.tracker?.isCritical === true) return true;

  const atkRoll = wf?.d20AttackRoll ?? wf?.attackRoll;
  if (atkRoll?.isCritical === true) return true;

  const dmgRolls = [...(wf?.damageRolls ?? [])];
  if (dmgRolls.some((r) => r?.isCritical === true || r?.options?.isCritical === true)) {
    return true;
  }

  const d20 =
    atkRoll?.dice?.find?.((d) => d.faces === 20)
    ?? atkRoll?.terms?.find?.((t) => t?.faces === 20)
    ?? null;
  if (!d20) return false;
  const critThreshold = Number(d20.options?.critical ?? atkRoll?.options?.critical ?? 20) || 20;
  // Only kept dice count (discarded = advantage/disadvantage reject).
  return (d20.results ?? []).some(
    (r) => !r?.discarded && r?.active !== false && Number(r?.result) >= critThreshold,
  );
}

function partbreakerDamageType(wf) {
  const rolled = wf?.item;
  return (
    String(
      wf?.defaultDamageType
      || wf?.damageDetail?.[0]?.type
      || partbreakerTypeFromSet(rolled?.system?.damage?.base?.types)
      || partbreakerTypeFromSet(wf?.activity?.damage?.parts?.[0]?.types)
      || "slashing",
    )
      .toLowerCase()
      .trim() || "slashing"
  );
}

function partbreakerDisarm() {
  globalThis.__amellwindRuneHooks ??= {};
  const hooks = globalThis.__amellwindRuneHooks[item.uuid] ?? [];
  for (const h of hooks) {
    if (h?.event != null && h?.id != null) Hooks.off(h.event, h.id);
  }
  delete globalThis.__amellwindRuneHooks[item.uuid];
}

async function partbreakerApply(wf) {
  try {
    if (!wf || !actorDoc || !item) return;
    if (!item.system?.equipped) return;
    const applied = getRuneFlag(item, "applied");
    if (!applied || applied.side !== "weapon") return;

    const attacker = wf.actor ?? wf.token?.actor;
    if (!attacker || attacker.uuid !== actorDoc.uuid) return;
    if (!partbreakerIsWeaponAttack(wf)) return;
    if (!partbreakerIsCrit(wf)) return;

    const targets = [...(wf.hitTargets ?? [])].filter(Boolean);
    if (!targets.length) return;

    globalThis.__amellwindPartbreaker ??= new Set();
    const wid = String(wf.id ?? wf.uuid ?? wf.itemCardId ?? `${wf.item?.id}-${wf.damageTotal ?? ""}`);
    const dedupeKey = `${item.uuid}:${wid}`;
    if (globalThis.__amellwindPartbreaker.has(dedupeKey)) return;
    globalThis.__amellwindPartbreaker.add(dedupeKey);

    const dtype = partbreakerDamageType(wf);
    const rollData = actorDoc.getRollData?.() ?? {};
    const RollClass = CONFIG.Dice.DamageRoll ?? Roll;
    const damageRoll = await new RollClass(`1d4[${dtype}]`, rollData).evaluate();
    await damageRoll.toMessage({
      speaker: ChatMessage.getSpeaker({ actor: actorDoc }),
      flavor: `Partbreaker (${dtype})`,
    });

    if (globalThis.MidiQOL?.applyTokenDamage) {
      await MidiQOL.applyTokenDamage(
        [{ damage: damageRoll.total, type: dtype }],
        damageRoll.total,
        new Set(targets),
        wf.item ?? item,
        new Set(),
      );
    } else {
      for (const t of targets) {
        const targetActor = t.actor ?? t.document?.actor;
        if (typeof targetActor?.applyDamage === "function") {
          await targetActor.applyDamage([{ value: damageRoll.total, type: dtype }]);
        }
      }
    }
  } catch (err) {
    console.error(`${runeName} Partbreaker apply failed`, err);
    ui.notifications?.error?.(`${runeName}: Partbreaker failed (see F12).`);
  }
}

function partbreakerArm() {
  partbreakerDisarm();
  globalThis.__amellwindRuneHooks ??= {};
  const hooks = [];
  const handler = (wf) => {
    partbreakerApply(wf);
  };
  for (const event of PARTBREAKER_HOOK_EVENTS) {
    hooks.push({ event, id: Hooks.on(event, handler) });
  }
  globalThis.__amellwindRuneHooks[item.uuid] = hooks;
  console.log(`${runeName}: Partbreaker armed`, hooks);
  ui.notifications?.info?.(`${runeName}: Partbreaker armed — +1d4 on weapon critical hits.`);
}

async function runeCleanup() {
  partbreakerDisarm();
  if (!actorDoc) return;
  const mine = actorDoc.effects.filter((e) => getRuneFlag(e, "runeClone") && e.origin === item.uuid);
  if (mine.length) await actorDoc.deleteEmbeddedDocuments("ActiveEffect", mine.map((e) => e.id));
  await unsetRuneFlag(item, "applied");
}

function runeAeName(side, matName, trinket) {
  let n = `${runeName}-${side}`;
  if (matName) n += `-${matName}`;
  if (trinket) n += " (Trinket)";
  return n;
}

async function runeApplySide(side, trinket) {
  if (!actorDoc) return;
  const blueprints = item.effects.filter((e) => getRuneFlag(e, "runeSide") === side);
  const docs = blueprints.map((e) => {
    const o = e.toObject();
    delete o._id;
    o.origin = item.uuid;
    o.disabled = false;
    o.transfer = false;
    o.name = runeAeName(side, getRuneFlag(e, "materialEffectName"), trinket);
    foundry.utils.setProperty(o, `flags.${FLAG}.runeClone`, true);
    foundry.utils.setProperty(o, "flags.dae.showIcon", false);
    return o;
  });
  if (docs.length) await actorDoc.createEmbeddedDocuments("ActiveEffect", docs);
  await setRuneFlag(item, "applied", { side, trinket: !!trinket });
  if (side === "weapon") partbreakerArm();
  else partbreakerDisarm();
}

if (arg0 === "on") {
  if (!actorDoc) {
    ui.notifications?.error?.(`${runeName}: no actor found for rune equip.`);
    return;
  }
  try {
    await runeCleanup();
    const sides = getRuneFlag(item, "sides") ?? {};
    const available = Object.keys(sides).filter((s) => sides[s]);
    if (!available.length) {
      ui.notifications?.warn?.(`${runeName}: no rune sides configured.`);
      return;
    }
    const radios = available
      .map((s, i) => `<label style="display:block;margin:.15rem 0"><input type="radio" name="runeSide" value="${s}" ${i === 0 ? "checked" : ""}/> ${sides[s].label ?? s}</label>`)
      .join("");
    const content = `<form class="dnd5e2"><p>Choose which effect to activate for <strong>${runeName}</strong>:</p>${radios}<hr/><label style="display:block;margin-top:.35rem"><input type="checkbox" name="runeTrinket"/> Equipped in a trinket</label></form>`;
    const choice = await new Promise((resolve) => {
      new Dialog({
        title: `${runeName} Rune`,
        content,
        buttons: {
          ok: {
            icon: '<i class="fas fa-check"></i>',
            label: "Activate",
            callback: (html) => resolve({
              side: html.find('input[name="runeSide"]:checked').val(),
              trinket: html.find('input[name="runeTrinket"]').is(":checked"),
            }),
          },
          cancel: {
            icon: '<i class="fas fa-times"></i>',
            label: "Cancel",
            callback: () => resolve(null),
          },
        },
        default: "ok",
        close: () => resolve(null),
      }).render(true);
    });
    if (!choice || !choice.side) {
      await item.update({ "system.equipped": false });
      return;
    }
    await runeApplySide(choice.side, choice.trinket);
  } catch (err) {
    console.error(`${runeName} equip failed`, err);
    ui.notifications?.error?.(`${runeName}: equip automation failed (see F12).`);
  }
  return;
}

if (arg0 === "off") {
  await runeCleanup();
  return;
}
if (arg0 === "each") return;
